(954123, 111876, 19952, '<td valign="top">Other than that unusual greenness around the right eye, this is an amazing image. It might look a little more intense with some motion, but that may be a personal preference. Great job.</td>', 'Other than that unusual greenness around the right eye, this is an amazing image. It might look a little more intense with some motion, but that may be a personal preference. Great job.', '2004-10-11 09:18:20.000000', NULL, 1),
(954124, 111848, 14448, '<td valign="top">Nice composition.  My eyes are drawn to her cleavage rather than to her legs though, since that''s what is bright in the image, and where the lines flow.  A different lighting arrangement could shift the emphasis.  Still, an elegant, appealing shot.</td>', 'Nice composition.  My eyes are drawn to her cleavage rather than to her legs though, since that''s what is bright in the image, and where the lines flow.  A different lighting arrangement could shift the emphasis.  Still, an elegant, appealing shot.', '2004-10-11 09:24:48.000000', NULL, 1),
(954132, 111212, 19952, '<td valign="top">Nice composition and a great subject. The colors seem a little pale, so I think the image might benefit from increased contrast or saturation. Otherwise, really nice shot.</td>', 'Nice composition and a great subject. The colors seem a little pale, so I think the image might benefit from increased contrast or saturation. Otherwise, really nice shot.', '2004-10-11 09:57:36.000000', NULL, 1),
(954135, 110501, 19952, '<td valign="top">I think you accomplished exactly what this challenge is about. The light could be a bit softer, but overall this is a really superb shot. Great job.</td>', 'I think you accomplished exactly what this challenge is about. The light could be a bit softer, but overall this is a really superb shot. Great job.', '2004-10-11 09:59:22.000000', NULL, 1),
(954140, 111212, 14453, '<td valign="top">For me it has a feeling of recent ''''Déja vu"!  Nice picture anyway! 7</td>', 'For me it has a feeling of recent ''''Déja vu"!  Nice picture anyway! 7', '2004-10-11 10:10:18.000000', NULL, 1),
(954150, 111547, 26756, '<td valign="top">I like the DOF you used to really bring out the eyes while leaving other parts of the face a bit out of focus.  Really draws you in.  Wonderful use of color too.  Great "National Geographic" type photo. Good job.</td>', 'I like the DOF you used to really bring out the eyes while leaving other parts of the face a bit out of focus.  Really draws you in.  Wonderful use of color too.  Great "National Geographic" type photo. Good job.', '2004-10-11 10:26:28.000000', NULL, 1),
