(954348, 111481, 2780, '<td valign="top">The DoF here works great. The photo is a little grainy but that doesn''t detract at all. 10</td>', 'The DoF here works great. The photo is a little grainy but that doesn''t detract at all. 10', '2004-10-11 13:26:30.000000', NULL, 1),
(954349, 111547, 2780, '<td valign="top">This photo is amazing. The contrast, vibrant colours, emotion, and everything else, are all fantastic. 10</td>', 'This photo is amazing. The contrast, vibrant colours, emotion, and everything else, are all fantastic. 10', '2004-10-11 13:27:08.000000', NULL, 1),
