(956020, 111547, 16046, '<td valign="top">Well done, great DOF</td>', 'Well done, great DOF', '2004-10-12 17:23:46.000000', NULL, 1),
(956063, 111481, 26596, '<td valign="top">Spectacular.  Perfectly executed shot.  I hope this wins the challenge.  Great DOF - what lense did you use.</td>', 'Spectacular.  Perfectly executed shot.  I hope this wins the challenge.  Great DOF - what lense did you use.', '2004-10-12 17:52:29.000000', NULL, 1),
(956113, 110172, 20115, '<td valign="top">Great!  Looks like a hard shot to set up.  I don''t now if I could be that patient.</td>', 'Great!  Looks like a hard shot to set up.  I don''t now if I could be that patient.', '2004-10-12 18:55:08.000000', NULL, 1),
(956128, 111388, 20779, '<td valign="top">I just love the soft finish to this and the wonderful composition. She looks a lot like the beautfiul Natalie Wood to me here.</td>', 'I just love the soft finish to this and the wonderful composition. She looks a lot like the beautfiul Natalie Wood to me here.', '2004-10-12 19:09:56.000000', NULL, 1),
(956129, 111497, 20779, '<td valign="top">Love this one. Very engaging and intense. Dead on focus on the eyes.</td>', 'Love this one. Very engaging and intense. Dead on focus on the eyes.', '2004-10-12 19:10:35.000000', NULL, 1),
(956130, 111358, 20779, '<td valign="top">Beautiful position of the eye caught and used. Perfect colors and balance.</td>', 'Beautiful position of the eye caught and used. Perfect colors and balance.', '2004-10-12 19:11:01.000000', NULL, 1),
(956131, 111481, 20779, '<td valign="top">What a great, clear capture. Wonderful composition wihtin the frame.</td>', 'What a great, clear capture. Wonderful composition wihtin the frame.', '2004-10-12 19:12:53.000000', NULL, 1),
(956132, 111687, 2337, '<td valign="top">LoL :)  Nice to see someone put humor ahead of score :)</td>', 'LoL :)  Nice to see someone put humor ahead of score :)', '2004-10-12 19:13:17.000000', NULL, 1),
(956133, 111321, 20779, '<td valign="top">Well this lightened my day! Great shot!</td>', 'Well this lightened my day! Great shot!', '2004-10-12 19:13:31.000000', NULL, 1),
(956135, 111875, 2337, '<td valign="top">While I''m not personnaly a big fan of photos, this is very well executed :)  Congrats on a great shot</td>', 'While I''m not personnaly a big fan of photos, this is very well executed :)  Congrats on a great shot', '2004-10-12 19:14:56.000000', NULL, 1),
(956136, 111571, 2337, '<td valign="top">Frame it... Hang it on a wall... Excellent portrait... ~10~</td>', 'Frame it... Hang it on a wall... Excellent portrait... ~10~', '2004-10-12 19:17:55.000000', NULL, 1),
(956137, 111842, 25017, '<td valign="top">what a wonderful imagination fantastic composition well done</td>', 'what a wonderful imagination fantastic composition well done', '2004-10-12 19:20:06.000000', NULL, 1),
(956139, 110501, 25017, '<td valign="top">a lovely emotional photo, she looks sad, I love the way her hair and arm frames her eyes</td>', 'a lovely emotional photo, she looks sad, I love the way her hair and arm frames her eyes', '2004-10-12 19:20:56.000000', NULL, 1),
(956140, 111232, 25017, '<td valign="top">A wonderul capture, I love the B &amp; W</td>', 'A wonderul capture, I love the B & W', '2004-10-12 19:21:48.000000', NULL, 1),
(956142, 111727, 2337, '<td valign="top">Great choice of background... The wall matches the gentleman''s texture and expression... Well done!</td>', 'Great choice of background... The wall matches the gentleman''s texture and expression... Well done!', '2004-10-12 19:23:58.000000', NULL, 1),
(956143, 111863, 22748, '<td valign="top">Nice and sharp. However, it could use a little more "pop", maybe some boosting of the curves, and the pose is not as engaging as it could be. Good idea though.</td>', 'Nice and sharp. However, it could use a little more "pop", maybe some boosting of the curves, and the pose is not as engaging as it could be. Good idea though.', '2004-10-12 19:24:11.000000', NULL, 1),
(956144, 111370, 7778, '<td valign="top">An excellent portrait with wonderful timing which speaks of more than the attributes awarded the subject via the title. The image is technically (exposure/lighting/dof/sharpness) immaculate while the manner (perspective/choice of b &amp; w/of subject/composition) strikes a remarkable balance between boldness and delicacy.<br/> <br/>The irrepressible freshness this photograph communicates is a rare treat indeed. I am transported. ;-)</td>', 'An excellent portrait with wonderful timing which speaks of more than the attributes awarded the subject via the title. The image is technically (exposure/lighting/dof/sharpness) immaculate while the manner (perspective/choice of b & w/of subject/composition) strikes a remarkable balance between boldness and delicacy. The irrepressible freshness this photograph communicates is a rare treat indeed. I am transported. ;-)', '2004-10-12 19:24:34.000000', NULL, 1),
(956145, 111827, 26464, '<td valign="top">nice photo and subject, unfortunately (although it is very classy) the necklace she is wearing distracts me from the hair. <br/></td>', 'nice photo and subject, unfortunately (although it is very classy) the necklace she is wearing distracts me from the hair. ', '2004-10-12 19:25:10.000000', NULL, 1),
(956146, 111887, 22748, '<td valign="top">Cool. It catches the attention. Nice contrast and sharpness.</td>', 'Cool. It catches the attention. Nice contrast and sharpness.', '2004-10-12 19:25:25.000000', NULL, 1),
(956148, 111845, 26464, '<td valign="top">the focus is slightly more on the board and just missed the subject. reverse the two focal points and you have a better photo IMO.<br/></td>', 'the focus is slightly more on the board and just missed the subject. reverse the two focal points and you have a better photo IMO.', '2004-10-12 19:26:25.000000', NULL, 1),
(956150, 110172, 26464, '<td valign="top">great work. you''ve met the challenge dead-on and produced a great image in the process. i give you a 9.<br/></td>', 'great work. you''ve met the challenge dead-on and produced a great image in the process. i give you a 9.', '2004-10-12 19:28:43.000000', NULL, 1),
(956151, 111812, 26464, '<td valign="top">very nice take on a recurring eye theme. and super sharp too.<br/></td>', 'very nice take on a recurring eye theme. and super sharp too.', '2004-10-12 19:29:22.000000', NULL, 1),
