(958122, 111816, 19608, '<td valign="top">"Take a picture of a person''s defining feature."  Not exactly a person in my view - but a fantastic job of carving.</td>', '"Take a picture of a person''s defining feature."  Not exactly a person in my view - but a fantastic job of carving.', '2004-10-13 16:48:26.000000', NULL, 1),
