(958130, 111835, 19608, '<td valign="top">Unusual compositon that works very well.  Nice exposure and colors.</td>', 'Unusual compositon that works very well.  Nice exposure and colors.', '2004-10-13 16:53:12.000000', NULL, 1),
(958133, 111232, 19608, '<td valign="top">Superb B&amp;W - great job of conversion.  Model is a perfect study in character.</td>', 'Superb B&W - great job of conversion.  Model is a perfect study in character.', '2004-10-13 16:54:44.000000', NULL, 1),
