(961471, 111728, 16636, '<td valign="top">you,ve  caught the eyes just right and the tone of the image is nice, although the fingers are a bit distracting to me, good luck</td>', 'you,ve  caught the eyes just right and the tone of the image is nice, although the fingers are a bit distracting to me, good luck', '2004-10-16 06:15:07.000000', NULL, 1),
