INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(963564, 111812, 2716, '<td valign="top">Great shot Arny.  They eye really pulled me in.  One of my favorites of the challenge.</td>', 'Great shot Arny.  They eye really pulled me in.  One of my favorites of the challenge.', '2004-10-18 07:32:11.000000', NULL, 0),
(963615, 111661, 23458, '<td valign="top">I think this is a perfect example of voters being a little too anal when it comes to ''meeting the challenge'' - I really like the lighting here and the sense of humour is refreshing.<br/> <br/>Cheers</td>', 'I think this is a perfect example of voters being a little too anal when it comes to ''meeting the challenge'' - I really like the lighting here and the sense of humour is refreshing. Cheers', '2004-10-18 08:51:55.000000', NULL, 0),
(963622, 111473, 10080, '<td valign="top">Beautiful job! Congrats!<br/></td>', 'Beautiful job! Congrats!', '2004-10-18 08:55:03.000000', NULL, 0),
(963624, 111511, 280, '<td valign="top">Didn''t vote on this challenge, but I would have thought that this shot would have come higher. Great idea and take on 2001, just a shame it seemed to go over so many heads.</td>', 'Didn''t vote on this challenge, but I would have thought that this shot would have come higher. Great idea and take on 2001, just a shame it seemed to go over so many heads.', '2004-10-18 08:57:09.000000', NULL, 0),
(963625, 111481, 10080, '<td valign="top">Great job jacko! Wonderful shot!!!</td>', 'Great job jacko! Wonderful shot!!!', '2004-10-18 08:58:39.000000', NULL, 0),
(963626, 111474, 22975, '<td valign="top">I didn''t want his eyes looking at the camera... they confront you, in a sense, when they do, and he such a non-confrontational man... I rather *liked* the passive nature of this, and am standing by my choice to photograph him in this manner.</td>', 'I didn''t want his eyes looking at the camera... they confront you, in a sense, when they do, and he such a non-confrontational man... I rather *liked* the passive nature of this, and am standing by my choice to photograph him in this manner.', '2004-10-18 08:59:32.000000', NULL, 0),
(963628, 111876, 10080, '<td valign="top">Very cool shot! Lots of emotion! Congrats!</td>', 'Very cool shot! Lots of emotion! Congrats!', '2004-10-18 09:02:33.000000', NULL, 0),
(963632, 111728, 10080, '<td valign="top">Thank you for all the wonderful comments, and constructive criticism. I learn a bit everyday by entering challenges, and that only makes me look a little further into my efforts! Thanks to Gracie girl too! I would use her for every contest, but that''d give me away! My best to you all!</td>', 'Thank you for all the wonderful comments, and constructive criticism. I learn a bit everyday by entering challenges, and that only makes me look a little further into my efforts! Thanks to Gracie girl too! I would use her for every contest, but that''d give me away! My best to you all!', '2004-10-18 09:07:55.000000', NULL, 0),
(963636, 111481, 11793, '<td valign="top">well done, and quite deceiving.<br/></td>', 'well done, and quite deceiving.', '2004-10-18 09:11:32.000000', NULL, 0),
(963640, 111547, 6532, '<td valign="top">This was one of my top picks...good job!  I guess I have been here for too long... I knew it was yours.  Congratulations!</td>', 'This was one of my top picks...good job!  I guess I have been here for too long... I knew it was yours.  Congratulations!', '2004-10-18 09:16:59.000000', NULL, 0),
(963653, 111481, 11738, '<td valign="top">Congrats bro!  Another badass shot deserving a bad ass ribbon, which it got!<br/> <br/>Keep up the excellent work.  I''m glad to see both Doucette brothers on the the top 10 page again.  It''s been a while.</td>', 'Congrats bro!  Another badass shot deserving a bad ass ribbon, which it got! Keep up the excellent work.  I''m glad to see both Doucette brothers on the the top 10 page again.  It''s been a while.', '2004-10-18 09:47:22.000000', NULL, 0),
(963662, 111547, 10413, '<td valign="top">Congratulations on a blue.  This was by far my favorite.  Your work is exceptional!</td>', 'Congratulations on a blue.  This was by far my favorite.  Your work is exceptional!', '2004-10-18 09:57:01.000000', NULL, 0),
(963664, 111473, 10413, '<td valign="top">A great shot! Congratualtions on red.</td>', 'A great shot! Congratualtions on red.', '2004-10-18 09:57:57.000000', NULL, 0),
(963666, 111481, 10413, '<td valign="top">One of my top picks. I can''t beleieve this is your sons eyelashes. He''ll have girls all over him with those lashes.  Congratulations Jacko!</td>', 'One of my top picks. I can''t beleieve this is your sons eyelashes. He''ll have girls all over him with those lashes.  Congratulations Jacko!', '2004-10-18 10:00:51.000000', NULL, 0),
(963667, 111473, 13365, '<td valign="top">Thanks everyone for all your votes and comments!!!<br/> <br/>And thanks to my wife for letting me spray cold water on her and take her photograph.</td>', 'Thanks everyone for all your votes and comments!!! And thanks to my wife for letting me spray cold water on her and take her photograph.', '2004-10-18 10:01:58.000000', NULL, 0),
(963669, 111809, 11738, '<td valign="top">Thanks for all the comments and votes folks.<br/> <br/>This shot has finally put me over the 5.9+ Average Vote Received barrier.  <br/> <br/>I had fun with this shot.  It''s another last minute idea.  My original plan was to create a nose extension using some sort of clay or Halloween facial putty (that''s why I went for a silhouette image), but I just didn''t have the time.  I think a bigger shnoz would have made the image place a bit higher.<br/> <br/>Thanks again.</td>', 'Thanks for all the comments and votes folks. This shot has finally put me over the 5.9+ Average Vote Received barrier.   I had fun with this shot.  It''s another last minute idea.  My original plan was to create a nose extension using some sort of clay or Halloween facial putty (that''s why I went for a silhouette image), but I just didn''t have the time.  I think a bigger shnoz would have made the image place a bit higher. Thanks again.', '2004-10-18 10:02:39.000000', NULL, 0),
(963680, 111473, 9821, '<td valign="top">Top notch stuff every time ... congratulations again.</td>', 'Top notch stuff every time ... congratulations again.', '2004-10-18 10:18:35.000000', NULL, 0),
